function NotificationForm() {
  const [preference, setPreference] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (preference) {
      setSubmitted(true);
      console.log('Form submitted with preference:', preference);
    }
  };

  if (submitted) {
    return (
      <main className="card" role="status" aria-live="polite">
        <h1>Preferences Saved</h1>
        <p>Your preference for <strong>{preference}</strong> has been saved.</p>
        <button 
