 const { useState } = React;

 function NotificationForm() {
   const [preference, setPreference] = useState('');
   const [submitted, setSubmitted] = useState(false);

   const handleSubmit = (e) => {
     e.preventDefault();
     if (preference) {
       setSubmitted(true);
       console.log('Form submitted with preference:', preference);
     }
   };

   if (submitted) {
     return (
       <main className="card" role="status" aria-live="polite">
         <h1>Preferences Saved</h1>
         <p>Your preference for <strong>{preference}</strong> has been saved.</p>
         <button 
           className="submit-button" 
           onClick={() => {
             setSubmitted(false);
             setPreference('');
           }}
         >
           Back to settings
         </button>
       </main>
     );
   }

   return (
     <main className="card">
       <h1>Settings</h1>
       <p style={{ fontSize: '0.875rem', color: '#6b7280', marginBottom: '1rem' }}>
         Fields marked with an asterisk (<span aria-hidden="true">*</span>) are required.
       </p>
       <form onSubmit={handleSubmit}>
         <div className="form-field">
           <fieldset>
             <legend>
               How do you prefer to receive notifications? <span aria-hidden="true">*</span>
             </legend>
             <div className="radio-group">
               {[
                 { id: 'email', label: 'Email' },
                 { id: 'sms', label: 'SMS' },
                 { id: 'push', label: 'Push Notifications' }
               ].map((option) => (
                 <div key={option.id} className="radio-option">
                   <input
                     type="radio"
                     id={option.id}
                     name="notification-preference"
                     value={option.id}
                     checked={preference === option.id}
                     onChange={(e) => setPreference(e.target.value)}
                     required
                   />
                   <label htmlFor={option.id}>{option.label}</label>
                 </div>
               ))}
             </div>
           </fieldset>
         </div>
         <button type="submit" className="submit-button">
           Save Preferences
         </button>
       </form>
     </main>
   );
 }

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<NotificationForm />);

')

